contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes calldata encodedParameters, address ownedBy, address newAlloSettings) public payable {
        require(address(this).code.length > 0);
        c.initialize();
        assert(c.owner() == address(this));
        c.updateAlloSettings(newAlloSettings);
        c.updateRoundImplementation(payable(address(this)));
        c.programOperators(address(this), true);
        bool reverted;
        address clone;
        try c.create(encodedParameters, ownedBy) returns (address r) { clone = r; reverted = false; } catch { reverted = true; }
        assert(!reverted
            && clone != address(0)
            && clone != address(this)
            && clone.code.length > 0
            && c.alloSettings() == newAlloSettings
            && c.roundImplementation() == address(this)
            && c.owner() == address(this));
    }
    fallback() external payable {}
    receive() external payable {}
}

