    constructor(C _c) { c = _c; }
    function run(address impl, address settings, bytes calldata params, address ownedBy) public {
        require(impl != address(0));
        require(settings != address(0));
        // setup: owner (this contract) sets implementation and settings
        c.updateRoundImplementation(payable(impl));
        c.updateAlloSettings(settings);
        // rule 1: non-operator cannot create
        bool revertedNonOp;
        try c.create(params, ownedBy) { revertedNonOp = false; }
        catch { revertedNonOp = true; }
        // become operator and create
        c.setProgramOperator(address(this), true);
        address clone = c.create(params, ownedBy);
        assert(
            revertedNonOp
            && clone != address(0)
            && clone.code.length > 0
            && clone != impl
            && clone != settings
            && clone != address(c)
        );
    }
    receive() external payable {}
}

