        // first initialize succeeds
        bool init2Reverted;
        c.initialize();
        try c.initialize() { init2Reverted = false; }
        catch { init2Reverted = true; }
        // zero address must revert
        bool zeroReverted;
        try c.updateRoundImplementation(payable(address(0))) { zeroReverted = false; }
        catch { zeroReverted = true; }
        // valid set is reflected by the public getter
        c.updateRoundImplementation(payable(impl));
        address stored1 = c.roundImplementation();
        c.updateRoundImplementation(payable(impl2));
        address stored2 = c.roundImplementation();
        assert(
            init2Reverted
            && zeroReverted
            && stored1 == impl
            && stored2 == impl2
        );
    }
    receive() external payable {}
}

